        }
    }

/// Deliver an incoming message from the network to the actor.
pub async fn handle_incoming(&self, m: Message<T>) {
    let _ = self.incoming_tx.send(m).await;
}

/// it's closed. Since this runs on the single actor loop, that blocked
/// tick/election/command processing for the node entirely, not just delayed
/// egress. Uses a tiny `outgoing_capacity` and never drains it, so it fills
/// up almost immediately (the node has configured peers and sends BLE
/// heartbeats regardless of whether anyone's listening).
///
/// Notify-path (`TaggedProposal` / `Assigned`) backpressure is covered by
/// [`notify_egress_does_not_stall_when_outgoing_full`].
#[tokio::test]
async fn full_outgoing_channel_does_not_stall_actor_loop() {
    let nodes: Vec<NodeId> = vec![1, 2, 3];
    let cfg = RuntimeConfig {
        tick_period: Duration::from_millis(2),
        egress_period: Duration::from_millis(1),
        outgoing_capacity: 2,
        ..Default::default()
    };
    let op = build_op(1, nodes);
    let h = spawn_actor::<TestEntry, MemoryStorage<TestEntry>, TokioRuntime>(op, cfg);

    // Let the outgoing channel fill up completely without ever draining it.
    tokio::time::sleep(Duration::from_millis(100)).await;

    // The actor loop must still be responsive to commands -- if
    // flush_outgoing blocked on a full channel, this would hang.
    let idx = timeout(Duration::from_millis(500), h.decided_idx())
        .await
        .expect("actor loop appears stalled with a full outgoing channel");
    assert_eq!(idx, 0);

    // Draining now should still deliver messages (not silently and
    // permanently lost) once the consumer catches up.
    let out = h.outgoing_messages();
    timeout(Duration::from_secs(2), out.recv())
        .await
        .expect("no message ever arrived once draining resumed")
        .expect("outgoing channel closed unexpectedly");
}

/// Like `spawn_cluster`, but each node's outgoing drain can be paused via the
/// returned per-pid flags. While a node's flag is `true`, its drain task stops
/// calling `recv`, so that node's bounded `outgoing_messages` channel fills
/// and further egress hits backpressure -- without tearing down the rest of

fn drain_notifiers(&mut self) {
    let decided = self.op.get_decided_idx();
    let now = Instant::now();
    let cur_ballot = self.op.get_promise();
    let old = std::mem::take(&mut self.pending);
    for p in old {
        match p.assigned {
            Some((idx, _)) if idx <= decided => {
                let _ = p.reply.send(Ok(idx));
            }
            Some((idx, ballot)) if ballot < cur_ballot => {
                let _ = p
                    .reply
                    .send(Err(AppendError::Superseded { log_entry_idx: idx }));
            }
            _ if now > p.deadline => {
                let _ = p.reply.send(Err(AppendError::Timeout));
            }
            _ => self.pending.push_back(p),
        }
    }
}

/// Append an entry and await its decided log index.
///
/// Works from any node: the actor tags the entry with a unique id, routes it to
/// the current leader, and resolves the future when the assigned log index is
/// decided. If no leader is known yet, the call waits rather than failing fast --
/// it resolves once a leader is elected, or with `Timeout` if none is elected in
/// time. Fails with:
/// - [`AppendError::Timeout`] if the entry is not decided within
///   [`RuntimeConfig::append_notify_timeout`] (including when no leader was ever
///   elected in that time);
/// - [`AppendError::Propose`] if the underlying propose call itself failed (e.g. a
///   reconfiguration is already pending) -- only when this node owns the pending
///   call, otherwise it still resolves via `Timeout`;
/// - [`AppendError::Superseded`] if a leader change occurred before decision --
///   a heuristic, not a certainty; see its doc comment for why, and check the
///   returned index yourself if you need to know for sure;
/// - [`AppendError::TooManyOutstanding`] if [`RuntimeConfig::max_pending_appends`]
///   outstanding calls are already queued.
///
/// Uses [`RuntimeConfig::append_notify_timeout`] as the deadline; use
/// [`Self::append_notify_with_timeout`] to override it for a single call.
pub async fn append_notify(&self, entry: T) -> Result<usize, AppendError<T>> {
    self.append_notify_inner(entry, None).await
}
